// 1. Obtener respuestas del formulario (Trigger)
const respuestasForm = $("Google Sheets Trigger").last().json;

function extraerNumero(valor) {
  if (typeof valor === 'number') return valor;
  if (!valor) return 0;
  const match = String(valor).match(/\d+/);
  return match ? parseFloat(match[0]) : 0;
}

let presupuestoRaw = 0;
let tiempoRaw = 0;

// Buscar dinámicamente las claves de tiempo y presupuesto
for (const [key, value] of Object.entries(respuestasForm)) {
  const keyLower = key.toLowerCase();
  if (keyLower.includes('presupuesto')) {
    presupuestoRaw = value;
  } else if (keyLower.includes('tiempo')) {
    tiempoRaw = value;
  }
}

const presupuestoUsuario = extraerNumero(presupuestoRaw);
const tiempoUsuario = extraerNumero(tiempoRaw);

const nombreUsuario = respuestasForm["Nombre_adoptante"] || respuestasForm["Nombre completo"] || respuestasForm["Nombre"] || "Adoptante";
const emailUsuario = respuestasForm["Correo_adoptante"] || respuestasForm["Correo electrónico"] || respuestasForm["Correo"];

// 2. Obtener catálogo y ELIMINAR DUPLICADOS por ID_Mascota exacto de Google Sheets
const itemsRaw = $("Get row(s) in sheet").all().map(item => item.json);
const todasLasMascotas = Array.from(
  new Map(itemsRaw.map(pet => [pet.ID_Mascota, pet])).values()
);

// 3. Filtrar mascotas según criterios
const mascotasCompatibles = todasLasMascotas.filter(pet => {
  const costoPet = extraerNumero(pet.Presupuesto_Mensual_BS);
  const tiempoPet = extraerNumero(pet.Tiempo_Diario_Min);
  return costoPet <= presupuestoUsuario && tiempoPet <= tiempoUsuario;
});

let htmlCards = "";
let nombresArray = [];

if (mascotasCompatibles.length > 0) {
  mascotasCompatibles.forEach(pet => {
    nombresArray.push(pet.Nombre);
    htmlCards += `
      <div style="border: 1px solid #e0e0e0; border-radius: 8px; padding: 14px; margin-bottom: 12px; background-color: #ffffff;">
        <h3 style="color: #1a5276; margin-top: 0; margin-bottom: 8px;">🐾 ${pet.Nombre} (${pet.Especie})</h3>
        <p style="margin: 4px 0; color: #444;"><b>Nivel de energía:</b> ${pet.Nivel_Energia}</p>
        <p style="margin: 4px 0; color: #444;"><b>Costo estimado mensual:</b> ${pet.Presupuesto_Mensual_BS} BS</p>
        <p style="margin: 4px 0; color: #444;"><b>Tiempo diario de paseo:</b> ${pet.Tiempo_Diario_Min} min/día</p>
        <p style="margin: 8px 0 0 0; color: #666; font-style: italic;">"${pet.Perfil_Ideal}"</p>
      </div>`;
  });
}

// Devuelve las variables procesadas
return {
  json: {
    nombreUsuario: nombreUsuario,
    emailUsuario: emailUsuario,
    presupuestoUsuario: presupuestoUsuario,
    tiempoUsuario: tiempoUsuario,
    tieneMatch: mascotasCompatibles.length > 0,
    cantidadMatches: mascotasCompatibles.length,
    nombresMascotas: nombresArray.join(", "),
    htmlMascotas: htmlCards
  }
};
